INSERT IGNORE INTO `atividade_sustentavel` (`atividade_sustentavel_id`, `categoria_ambiental_id`, `nome`, `descricao`, `recompensa_xp`, `recompensa_credito`, `impacto_real_quantidade`, `impacto_real_unidade`, `ativa`) VALUES
(1, 1, 'Separação de Resíduos', 'Separe plástico, papel e metal do lixo orgânico na sua casa durante o dia.', 50, 30, '0.30', 'kg de resíduos reciclados', 1),
(2, 2, 'Banho Consciente', 'Reduza o tempo de banho para no máximo 5 minutos hoje.', 60, 40, '90.00', 'litros de água', 1),
(3, 3, 'Luzes Apagadas', 'Mantenha aparelhos fora da tomada e luzes apagadas em ambientes vazios.', 40, 20, '0.70', 'kWh de energia', 1),
(4, 4, 'Transporte Limpo', 'Caminhe, vá de bicicleta ou use transporte coletivo para um deslocamento.', 80, 50, '0.60', 'kg de CO₂ evitado', 1),
(5, 5, 'Plantio de Muda ou Horta', 'Cuide de uma planta, árvore ou horta comunitária na sua região.', 70, 45, '1.00', 'mudas plantadas', 1),
(6, 1, 'Descarte em Ecoponto ou Coleta Especial', 'Leve óleo usado, pilhas, baterias, lâmpadas ou eletrônicos a um ecoponto ou ponto de coleta parceiro.', 80, 50, '0.50', 'kg de resíduos reciclados', 1),
(7, 1, 'Compras sem Descartáveis', 'Use sacola reutilizável (ecobag), garrafa ou copo retornável ao fazer compras ou sair de casa.', 45, 25, '0.15', 'kg de resíduos evitados', 1),
(8, 2, 'Reuso de Água em Casa', 'Reaproveite a água da máquina de lavar, do enxágue ou da chuva para lavar quintal, calçada ou regar plantas.', 65, 40, '50.00', 'litros de água', 1),
(9, 2, 'Torneira Fechada na Rotina', 'Mantenha a torneira fechada ao escovar os dentes, ensaboar a louça ou lavar alimentos durante o dia.', 40, 25, '30.00', 'litros de água', 1),
(10, 3, 'Aproveitamento de Luz Natural', 'Abra cortinas e janelas para estudar ou trabalhar usando iluminação natural em vez de lâmpadas acesas.', 45, 25, '0.50', 'kWh de energia', 1),
(11, 3, 'Secagem ao Ar Livre ou Carga Cheia', 'Lave roupas juntando carga completa na máquina ou seque ao ar livre sem usar secadora elétrica.', 55, 35, '1.20', 'kWh de energia', 1),
(12, 4, 'Caminhada no Lugar do Carro', 'Faça um trajeto curto (mercado, escola, trabalho ou academia) a pé em vez de usar carro ou moto.', 60, 35, '0.35', 'kg de CO₂ evitado', 1),
(13, 4, 'Carona Solidária ou Revisão de Bicicleta', 'Compartilhe carona com colegas ou família, ou faça manutenção na bicicleta para manter o pedal ativo.', 70, 45, '0.80', 'kg de CO₂ evitado', 1),
(14, 5, 'Compostagem de Orgânicos', 'Separe cascas, restos de frutas, verduras ou borra de café para composteira doméstica ou ponto de compostagem.', 65, 40, '0.40', 'kg de orgânicos compostados', 1),
(15, 5, 'Limpeza de Área Verde ou Calçada', 'Recolha lixo descartado incorretamente em praça, parque, jardim ou na calçada do seu bairro e dê o destino certo.', 75, 50, '0.50', 'kg de resíduos coletados', 1);
