INSERT IGNORE INTO `quiz` (`quiz_id`, `titulo`, `descricao`, `categoria_ambiental_id`, `recompensa_xp`, `recompensa_credito`, `dificuldade`, `ativa`, `tipo`) VALUES
(1, 'Desafio dos Resíduos e Reciclagem', 'Teste seus conhecimentos sobre separação de lixo e tempo de decomposição.', 1, 40, 25, 'Fácil', 1, 'tematico'),
(2, 'Uso Consciente da Água', 'Aprenda práticas simples para evitar o desperdício de água potável.', 2, 40, 25, 'Médio', 1, 'tematico'),
(3, 'Eficiência Energética Urbana', 'Descubra como reduzir o consumo elétrico e diminuir emissões.', 3, 40, 25, 'Fácil', 1, 'tematico'),
(4, 'Coleta Seletiva Rápida', 'Três perguntas rápidas sobre as cores da coleta seletiva.', 1, 40, 25, 'Fácil', 1, 'diario'),
(5, 'Gotas que Contam', 'Pequenos hábitos que evitam o desperdício de água em casa.', 2, 40, 25, 'Fácil', 1, 'diario'),
(6, 'Liga e Desliga', 'Escolhas simples que reduzem o consumo de energia.', 3, 40, 25, 'Fácil', 1, 'diario'),
(7, 'Caminhos Limpos', 'Formas de se deslocar poluindo menos.', 4, 40, 25, 'Fácil', 1, 'diario'),
(8, 'Verde Todo Dia', 'O papel das plantas e dos animais na cidade.', 5, 40, 25, 'Fácil', 1, 'diario'),
(9, 'Resíduo no Lugar Certo', 'Para onde vão os resíduos que não podem ir para o lixo comum.', 1, 40, 25, 'Médio', 1, 'diario'),
(10, 'Água na Medida', 'De onde vem e como aproveitar melhor a água.', 2, 40, 25, 'Médio', 1, 'diario'),
(11, 'Grande Desafio dos Resíduos', 'Quiz da Semana: dez perguntas sobre coleta seletiva, os 3 Rs e o destino dos resíduos.', 1, 40, 25, 'Médio', 1, 'semanal'),
(12, 'Grande Desafio da Energia', 'Quiz da Semana: dez perguntas sobre fontes de energia, consumo e clima.', 3, 40, 25, 'Médio', 1, 'semanal'),
(13, 'Mobilidade Urbana Sustentável', 'Ciclofaixas, transporte coletivo e escolhas para se mover melhor na cidade.', 4, 40, 25, 'Fácil', 1, 'tematico'),
(14, 'Biodiversidade e Áreas Verdes', 'A variedade da vida e como as áreas verdes a protegem.', 5, 40, 25, 'Médio', 1, 'tematico'),
(15, 'Rios, Esgoto e Água Limpa', 'Como nossas atitudes chegam aos rios e lagos.', 2, 40, 25, 'Médio', 1, 'tematico');
