INSERT IGNORE INTO `alternativa` (`alternativa_id`, `pergunta_id`, `texto`, `correta`, `explicacao`) VALUES
(1011, 101, 'Vermelho', 0, NULL),
(1012, 101, 'Azul', 1, 'Na coleta seletiva padronizada, o azul é destinado ao papel/papelão, o vermelho ao plástico, o amarelo ao metal e o verde ao vidro.'),
(1013, 101, 'Amarelo', 0, NULL),
(1014, 101, 'Verde', 0, NULL),
(1021, 102, 'Cerca de 10 anos', 0, NULL),
(1022, 102, 'Cerca de 100 anos', 0, NULL),
(1023, 102, 'Mais de 400 anos', 1, 'O plástico PET é muito resistente e leva mais de 400 anos para se decompor, contaminando solos e oceanos com microplásticos.'),
(1024, 102, 'Não se decompõe', 0, NULL),
(2011, 201, 'Lavar a calçada com mangueira por 15 minutos', 1, 'Lavar a calçada com mangueira pode desperdiçar mais de 280 litros de água limpa em apenas 15 minutos.'),
(2012, 201, 'Usar a máquina de lavar louça cheia', 0, NULL),
(2013, 201, 'Escovar os dentes com a torneira fechada', 0, NULL),
(2014, 201, 'Tomar banho de 5 minutos', 0, NULL),
(3011, 301, 'O aparelho está desligado e não consome energia', 0, NULL),
(3012, 301, 'O aparelho continua consumindo energia silenciosamente', 1, 'O modo standby pode representar até 12% do consumo de energia de uma residência. Desligue da tomada quando não estiver usando.'),
(3013, 301, 'O aparelho está gerando energia limpa', 0, NULL),
(4011, 401, 'Azul', 0, NULL),
(4012, 401, 'Verde', 1, 'Pelo padrão de cores da Resolução CONAMA 275/2001, o verde é do vidro.'),
(4013, 401, 'Amarelo', 0, NULL),
(4014, 401, 'Vermelho', 0, NULL),
(4021, 402, 'Amarelo', 1, 'No padrão da Resolução CONAMA 275/2001, o amarelo é destinado aos metais, como latas.'),
(4022, 402, 'Verde', 0, NULL),
(4023, 402, 'Azul', 0, NULL),
(4024, 402, 'Marrom', 0, NULL),
(4031, 403, 'Misturar com o lixo orgânico', 0, NULL),
(4032, 403, 'Esvaziar e retirar o excesso de restos', 1, 'Esvaziar e tirar os restos evita mau cheiro e contaminação. Não é preciso gastar muita água lavando.'),
(4033, 403, 'Lavar com bastante água quente', 0, NULL),
(5011, 501, 'Deixar a torneira aberta', 0, NULL),
(5012, 501, 'Fechar a torneira enquanto escova', 1, 'Fechar a torneira durante a escovação evita que a água escorra pelo ralo sem uso.'),
(5013, 501, 'Usar água quente', 0, NULL),
(5021, 502, 'Não gasta água de verdade', 0, NULL),
(5022, 502, 'Desperdiça água o tempo todo', 1, 'Cada gota soma: ao longo de dias, um vazamento pequeno desperdiça muita água. Vale trocar a vedação.'),
(5023, 502, 'Só gasta água à noite', 0, NULL),
(5031, 503, 'Mangueira aberta por bastante tempo', 0, NULL),
(5032, 503, 'Vassoura e, se preciso, um balde com água reaproveitada', 1, 'Varrer primeiro e usar balde com água de reúso gasta muito menos que a mangueira.'),
(5033, 503, 'Lavadora ligada todos os dias', 0, NULL),
(6011, 601, 'Incandescente', 0, NULL),
(6012, 601, 'Halógena', 0, NULL),
(6013, 601, 'LED', 1, 'A lâmpada LED gasta bem menos energia para iluminar o mesmo ambiente e dura mais.'),
(6021, 602, 'Selo Procel', 1, 'O Selo Procel indica os produtos mais eficientes em consumo de energia na sua categoria.'),
(6022, 602, 'Selo do Inmetro de brinquedos', 0, NULL),
(6023, 602, 'Selo de orgânicos', 0, NULL),
(6031, 603, 'Guardar alimentos ainda quentes', 0, NULL),
(6032, 603, 'Evitar abrir a porta sem necessidade', 1, 'Cada abertura deixa o ar frio sair e o motor precisa trabalhar mais para resfriar de novo.'),
(6033, 603, 'Encostá-la no fogão', 0, NULL),
(7011, 701, 'Moto a gasolina', 0, NULL),
(7012, 701, 'Bicicleta', 1, 'A bicicleta usa só a força de quem pedala: não queima combustível nem solta fumaça.'),
(7013, 701, 'Carro a diesel', 0, NULL),
(7021, 702, 'Diminui a quantidade de carros nas ruas', 1, 'Com mais pessoas por carro, menos veículos circulam, com menos trânsito e menos emissões.'),
(7022, 702, 'Aumenta a velocidade dos carros', 0, NULL),
(7023, 702, 'Gasta mais combustível', 0, NULL),
(7031, 703, 'Polui mais por passageiro', 0, NULL),
(7032, 703, 'Polui menos por passageiro', 1, 'Um ônibus leva dezenas de pessoas de uma vez, então a emissão dividida por passageiro é bem menor.'),
(7033, 703, 'Polui exatamente igual', 0, NULL),
(8011, 801, 'Aumentam o calor do asfalto', 0, NULL),
(8012, 801, 'Fazem sombra e ajudam a baixar a temperatura', 1, 'A sombra e a transpiração das árvores refrescam ruas e praças.'),
(8013, 801, 'Não fazem diferença', 0, NULL),
(8021, 802, 'Polinização das plantas', 1, 'Ao visitar as flores, as abelhas levam o pólen de uma planta a outra e ajudam a formar frutos e sementes.'),
(8022, 802, 'Decomposição do lixo', 0, NULL),
(8023, 802, 'Produção de oxigênio', 0, NULL),
(8031, 803, 'Mata que só existe nas montanhas', 0, NULL),
(8032, 803, 'Vegetação nas margens de rios e lagos', 1, 'A mata ciliar protege as margens contra a erosão e evita que a terra caia nos rios.'),
(8033, 803, 'Plantação de eucalipto', 0, NULL),
(9011, 901, 'No lixo comum', 0, NULL),
(9012, 901, 'Na lixeira de metal', 0, NULL),
(9013, 901, 'Em pontos de coleta específicos', 1, 'Pilhas e baterias têm metais tóxicos e devem voltar ao fabricante por pontos de coleta (logística reversa).'),
(9021, 902, 'Jogar no ralo da pia', 0, NULL),
(9022, 902, 'Guardar em garrafa e levar a um ponto de coleta', 1, 'O óleo polui a água e entope canos. Coletado, pode virar sabão ou biocombustível.'),
(9023, 902, 'Jogar na terra do quintal', 0, NULL),
(9031, 903, 'Em plástico', 0, NULL),
(9032, 903, 'Em adubo', 1, 'Na compostagem, microrganismos decompõem a matéria orgânica e produzem adubo para plantas.'),
(9033, 903, 'Em vidro', 0, NULL),
(10011, 1001, 'Doce, nos rios', 0, NULL),
(10012, 1001, 'Salgada, nos oceanos', 1, 'A água salgada dos oceanos é a grande maioria. A água doce acessível é bem pouca, por isso é preciso cuidar dela.'),
(10013, 1001, 'Doce, nas geleiras', 0, NULL),
(10021, 1002, 'Para beber sem tratamento', 0, NULL),
(10022, 1002, 'Para regar plantas e lavar áreas externas', 1, 'Sem tratamento, a água da chuva serve para usos que não exigem água potável.'),
(10023, 1002, 'Para cozinhar', 0, NULL),
(10031, 1003, 'Lavar poucas peças várias vezes', 0, NULL),
(10032, 1003, 'Esperar juntar uma carga completa', 1, 'Com carga completa, a máquina faz menos ciclos e gasta menos água e energia no total.'),
(10033, 1003, 'Usar sempre o enxágue extra', 0, NULL),
(11011, 1101, 'Azul', 0, NULL),
(11012, 1101, 'Vermelho', 1, 'No padrão da Resolução CONAMA 275/2001, o vermelho é destinado ao plástico.'),
(11013, 1101, 'Verde', 0, NULL),
(11014, 1101, 'Amarelo', 0, NULL),
(11021, 1102, 'Marrom', 1, 'No padrão CONAMA, o marrom é para os resíduos orgânicos, como restos de comida.'),
(11022, 1102, 'Cinza', 0, NULL),
(11023, 1102, 'Branco', 0, NULL),
(11024, 1102, 'Preto', 0, NULL),
(11031, 1103, 'Papel', 0, NULL),
(11032, 1103, 'Resíduo não reciclável ou misturado', 1, 'O cinza é para o resíduo geral que não pode ser reciclado ou está misturado.'),
(11033, 1103, 'Vidro', 0, NULL),
(11041, 1104, 'Reunir, Revender, Recolher', 0, NULL),
(11042, 1104, 'Reduzir, Reutilizar, Reciclar', 1, 'Reduzir o consumo, reutilizar o que for possível e reciclar o que sobrar.'),
(11043, 1104, 'Reparar, Repor, Retirar', 0, NULL),
(11051, 1105, 'Reciclar', 0, NULL),
(11052, 1105, 'Reutilizar', 0, NULL),
(11053, 1105, 'Reduzir', 1, 'Reduzir evita que o resíduo exista. Reciclar é importante, mas gasta energia e recursos.'),
(11061, 1106, 'Porque são pesadas', 0, NULL),
(11062, 1106, 'Porque contêm mercúrio', 1, 'O mercúrio é tóxico. Essas lâmpadas devem ir para pontos de coleta específicos.'),
(11063, 1106, 'Porque são de plástico', 0, NULL),
(11071, 1107, 'Jogar no lixo comum', 0, NULL),
(11072, 1107, 'Levar a um ponto de coleta de eletrônicos', 1, 'Eletrônicos têm metais que podem ser recuperados e substâncias tóxicas. A logística reversa cuida disso.'),
(11073, 1107, 'Enterrar no quintal', 0, NULL),
(11081, 1108, 'Lei 9.605/1998', 0, NULL),
(11082, 1108, 'Lei 12.305/2010', 1, 'A Lei 12.305/2010 trata da gestão dos resíduos sólidos no Brasil, incluindo a logística reversa.'),
(11083, 1108, 'Lei 8.078/1990', 0, NULL),
(11091, 1109, 'Papel prensado', 0, NULL),
(11092, 1109, 'Poliestireno expandido, um tipo de plástico', 1, 'O isopor é poliestireno expandido (EPS), um plástico tecnicamente reciclável.'),
(11093, 1109, 'Vidro', 0, NULL),
(11101, 1110, 'Nenhuma, são iguais', 0, NULL),
(11102, 1110, 'O aterro tem o solo protegido e trata o chorume', 1, 'O aterro sanitário tem impermeabilização do solo e tratamento do chorume. O lixão contamina solo e água.'),
(11103, 1110, 'O lixão recicla todo o lixo', 0, NULL),
(12011, 1201, 'Carvão mineral', 0, NULL),
(12012, 1201, 'Petróleo', 0, NULL),
(12013, 1201, 'Solar', 1, 'A energia do sol se renova todos os dias. Carvão, petróleo e gás são fósseis e acabam.'),
(12014, 1201, 'Gás natural', 0, NULL),
(12021, 1202, 'Carvão', 0, NULL),
(12022, 1202, 'Hidrelétrica', 1, 'As usinas hidrelétricas respondem pela maior parte da eletricidade gerada no país.'),
(12023, 1202, 'Nuclear', 0, NULL),
(12031, 1203, 'Aquece a água do banho', 0, NULL),
(12032, 1203, 'Transforma a luz do sol em eletricidade', 1, 'As células fotovoltaicas convertem a luz do sol diretamente em energia elétrica.'),
(12033, 1203, 'Armazena vento', 0, NULL),
(12041, 1204, 'Das marés', 0, NULL),
(12042, 1204, 'Do vento', 1, 'As turbinas eólicas giram com o vento e geram eletricidade.'),
(12043, 1204, 'Do calor da Terra', 0, NULL),
(12051, 1205, 'Litros', 0, NULL),
(12052, 1205, 'Quilowatt-hora (kWh)', 1, 'O kWh mede a energia usada: a potência do aparelho multiplicada pelo tempo de uso.'),
(12053, 1205, 'Quilômetros', 0, NULL),
(12061, 1206, 'Carregador de celular', 0, NULL),
(12062, 1206, 'Lâmpada LED', 0, NULL),
(12063, 1206, 'Chuveiro elétrico', 1, 'O chuveiro elétrico tem potência alta. Banhos mais curtos fazem diferença na conta.'),
(12071, 1207, 'Fechar cortinas e acender as luzes', 0, NULL),
(12072, 1207, 'Abrir janelas e cortinas para usar a luz natural', 1, 'A luz natural é gratuita e evita acender lâmpadas sem necessidade.'),
(12073, 1207, 'Pintar as paredes de preto', 0, NULL),
(12081, 1208, 'A fotossíntese', 0, NULL),
(12082, 1208, 'A queima de combustíveis fósseis', 1, 'No mundo, queimar carvão, petróleo e gás libera gás carbônico, que retém calor na atmosfera. No Brasil, a maior fonte de emissões é o desmatamento.'),
(12083, 1208, 'A chuva', 0, NULL),
(12091, 1209, 'Com janelas abertas', 0, NULL),
(12092, 1209, 'Com portas e janelas fechadas e o filtro limpo', 1, 'Ambiente fechado e filtro limpo fazem o aparelho resfriar com menos esforço.'),
(12093, 1209, 'Na temperatura mais baixa possível', 0, NULL),
(12101, 1210, 'Deixar sempre na tomada', 0, NULL),
(12102, 1210, 'Tirar da tomada', 1, 'Mesmo sem aparelho conectado, alguns carregadores continuam consumindo um pouco de energia.'),
(12103, 1210, 'Cobrir com um pano', 0, NULL),
(13011, 1301, 'Uma faixa exclusiva para ônibus', 0, NULL),
(13012, 1301, 'Uma faixa da via sinalizada para bicicletas', 1, 'A ciclofaixa é uma faixa pintada na própria via, separada por sinalização, para as bicicletas.'),
(13013, 1301, 'Uma calçada para pedestres', 0, NULL),
(13021, 1302, 'Gasta combustível', 0, NULL),
(13022, 1302, 'Faz bem à saúde e não emite poluentes', 1, 'Caminhar é exercício e não polui. Para trajetos curtos, muitas vezes é tão rápido quanto o carro.'),
(13023, 1302, 'Aumenta o trânsito', 0, NULL),
(13031, 1303, 'Faz mais barulho', 0, NULL),
(13032, 1303, 'Não solta gases poluentes pelo escapamento', 1, 'O ônibus elétrico não queima combustível enquanto anda e também é mais silencioso.'),
(13033, 1303, 'Gasta mais diesel', 0, NULL),
(13041, 1304, 'Gastar menos combustível', 1, 'Pneus murchos aumentam o atrito e fazem o motor gastar mais combustível.'),
(13042, 1304, 'Andar mais rápido sempre', 0, NULL),
(13043, 1304, 'Poluir mais', 0, NULL),
(13051, 1305, 'Chinelo', 0, NULL),
(13052, 1305, 'Capacete', 1, 'O capacete protege a cabeça em caso de queda. Sinalização e atenção ao trânsito também são essenciais.'),
(13053, 1305, 'Fone de ouvido', 0, NULL),
(14011, 1401, 'Um tipo de adubo', 0, NULL),
(14012, 1401, 'A variedade de seres vivos de um lugar', 1, 'Biodiversidade é a variedade de plantas, animais, fungos e microrganismos e de seus ambientes.'),
(14013, 1401, 'Uma espécie de árvore', 0, NULL),
(14021, 1402, 'Caatinga', 0, NULL),
(14022, 1402, 'Pampa', 0, NULL),
(14023, 1402, 'Amazônia', 1, 'A Amazônia abriga a maior floresta tropical do planeta e uma enorme biodiversidade.'),
(14031, 1403, 'Aumento dos habitats dos animais', 0, NULL),
(14032, 1403, 'Perda de habitat e mais emissões de gases', 1, 'Derrubar a floresta destrói o lar de muitas espécies e libera o carbono guardado nas árvores.'),
(14033, 1403, 'Mais chuva garantida', 0, NULL),
(14041, 1404, 'Uma espécie nativa rara', 0, NULL),
(14042, 1404, 'Uma espécie de fora que se espalha e prejudica as nativas', 1, 'Espécies trazidas de outras regiões podem se espalhar sem controle e competir com as nativas.'),
(14043, 1404, 'Qualquer planta com flor', 0, NULL),
(14051, 1405, 'Porque crescem só em vasos', 0, NULL),
(14052, 1405, 'Porque atraem e alimentam a fauna local', 1, 'Plantas nativas oferecem abrigo e alimento para aves, insetos e outros animais da região.'),
(14053, 1405, 'Porque não precisam de luz', 0, NULL),
(15011, 1501, 'Nada, ele se dissolve', 0, NULL),
(15012, 1501, 'Polui a água e entope os canos', 1, 'O óleo não se mistura com a água, forma uma camada nos rios e gruda nos canos.'),
(15013, 1501, 'Limpa o encanamento', 0, NULL),
(15021, 1502, 'Para deixar o esgoto mais quente', 0, NULL),
(15022, 1502, 'Para evitar a contaminação de rios e mares', 1, 'O esgoto tratado volta à natureza com muito menos poluentes e riscos à saúde.'),
(15023, 1502, 'Para gastar mais água', 0, NULL),
(15031, 1503, 'Água mineral', 0, NULL),
(15032, 1503, 'Água tratada reaproveitada em usos não potáveis', 1, 'A água de reúso pode lavar ruas, regar jardins e abastecer descargas, poupando a água potável.'),
(15033, 1503, 'Água da chuva pura', 0, NULL),
(15041, 1504, 'O aumento da profundidade', 0, NULL),
(15042, 1504, 'O acúmulo de terra e sedimentos no fundo', 1, 'Sem a mata ciliar, a terra desce para o rio, que fica mais raso e pode transbordar.'),
(15043, 1504, 'A limpeza natural da água', 0, NULL),
(15051, 1505, 'Válvula de parede antiga', 0, NULL),
(15052, 1505, 'Caixa acoplada com duplo acionamento', 1, 'O duplo acionamento permite usar menos água quando não é preciso o volume total.'),
(15053, 1505, 'Descarga apertada várias vezes', 0, NULL);
